def _check_int(name, value):
    # bool is a subclass of int, but True/False are not meaningful sizes.
    if isinstance(value, bool) or not isinstance(value, int) or value < 1:
        raise ValueError(f"{name} must be an int >= 1, got {value!r}")


def chunk(items, size):
    _check_int("size", size)
    return [list(items[i:i + size]) for i in range(0, len(items), size)]


def sliding(items, size, step=1):
    _check_int("size", size)
    _check_int("step", step)
    last_start = len(items) - size
    return [list(items[i:i + size]) for i in range(0, last_start + 1, step)]
